DROP TABLE IF EXISTS `bpm_approval_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bpm_approval_template` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '模板ID',
  `code` varchar(100) NOT NULL COMMENT '模板编码',
  `name` varchar(200) NOT NULL COMMENT '模板名称',
  `category` varchar(50) DEFAULT NULL COMMENT '模板分类',
  `icon` varchar(200) DEFAULT NULL COMMENT '模板图标',
  `description` varchar(500) DEFAULT NULL COMMENT '模板描述',
  `form_config` text COMMENT '表单配置JSON',
  `flow_config` text COMMENT '流程配置JSON',
  `notify_config` text COMMENT '通知配置JSON',
  `use_count` bigint DEFAULT '0' COMMENT '使用次数',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `sort` int DEFAULT '0' COMMENT '排序',
  `creator` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bpm_approval_template_code` (`code`),
  KEY `idx_bpm_approval_template_category` (`category`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='审批模板表';
