--
-- Table structure for table `erp_finance_voucher`
--

DROP TABLE IF EXISTS `erp_finance_voucher`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `erp_finance_voucher` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `voucher_no` varchar(64) NOT NULL COMMENT '凭证号',
  `ledger_id` bigint NOT NULL COMMENT '账簿编号',
  `period_id` bigint NOT NULL COMMENT '期间编号',
  `template_id` bigint NOT NULL COMMENT '模板编号',
  `biz_type` int NOT NULL COMMENT '业务类型',
  `biz_id` bigint DEFAULT NULL COMMENT '业务单据编号',
  `biz_no` varchar(64) NOT NULL COMMENT '业务单号',
  `voucher_time` datetime NOT NULL COMMENT '凭证时间',
  `status` int NOT NULL DEFAULT '10' COMMENT '凭证状态',
  `total_debit_amount` decimal(24,6) NOT NULL DEFAULT '0.000000' COMMENT '借方合计',
  `total_credit_amount` decimal(24,6) NOT NULL DEFAULT '0.000000' COMMENT '贷方合计',
  `approve_user_id` bigint DEFAULT NULL COMMENT '审核人编号',
  `approve_time` datetime DEFAULT NULL COMMENT '审核时间',
  `post_user_id` bigint DEFAULT NULL COMMENT '过账人编号',
  `post_time` datetime DEFAULT NULL COMMENT '过账时间',
  `reverse_user_id` bigint DEFAULT NULL COMMENT '冲销操作人编号',
  `reverse_time` datetime DEFAULT NULL COMMENT '冲销时间',
  `reverse_voucher_id` bigint DEFAULT NULL COMMENT '冲销凭证编号',
  `reverse_from_voucher_id` bigint DEFAULT NULL COMMENT '来源凭证编号',
  `reverse_remark` varchar(255) DEFAULT NULL COMMENT '冲销说明',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) NOT NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) NOT NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_finance_voucher_no` (`voucher_no`,`deleted`),
  UNIQUE KEY `uk_finance_voucher_ledger_biz` (`ledger_id`,`biz_type`,`biz_id`,`deleted`),
  UNIQUE KEY `uk_finance_voucher_reverse_from` (`reverse_from_voucher_id`,`deleted`),
  KEY `idx_finance_voucher_page` (`ledger_id`,`period_id`,`biz_type`,`status`,`deleted`,`voucher_time`),
  KEY `idx_finance_voucher_biz_no` (`biz_no`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=982060 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='ERP 财务凭证';
/*!40101 SET character_set_client = @saved_cs_client */;

