--
-- Table structure for table `erp_finance_voucher_entry`
--

DROP TABLE IF EXISTS `erp_finance_voucher_entry`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `erp_finance_voucher_entry` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `voucher_id` bigint NOT NULL COMMENT '凭证编号',
  `entry_no` int NOT NULL COMMENT '分录顺序',
  `summary` varchar(255) DEFAULT NULL COMMENT '摘要',
  `subject_code` varchar(64) NOT NULL COMMENT '科目编码',
  `subject_name` varchar(128) NOT NULL COMMENT '科目名称',
  `debit_amount` decimal(24,6) NOT NULL DEFAULT '0.000000' COMMENT '借方金额',
  `credit_amount` decimal(24,6) NOT NULL DEFAULT '0.000000' COMMENT '贷方金额',
  `creator` varchar(64) NOT NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) NOT NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
