DROP TABLE IF EXISTS `erp_finance_voucher_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `erp_finance_voucher_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `voucher_id` bigint NOT NULL COMMENT '凭证编号',
  `operation_type` varchar(32) NOT NULL COMMENT '操作类型',
  `operation_result` varchar(32) DEFAULT NULL COMMENT '操作结果',
  `operation_detail` text COMMENT '操作详情',
  `operator` varchar(64) DEFAULT NULL COMMENT '操作人',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) NOT NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) NOT NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_finance_voucher_log_voucher` (`voucher_id`,`deleted`,`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=266 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='ERP 财务凭证日志';
/*!40101 SET character_set_client = @saved_cs_client */;

