--
-- Table structure for table `erp_finance_voucher_template`
--

DROP TABLE IF EXISTS `erp_finance_voucher_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `erp_finance_voucher_template` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `ledger_id` bigint NOT NULL COMMENT '账簿编号',
  `biz_type` int NOT NULL COMMENT '业务类型',
  `research_category` int DEFAULT NULL COMMENT '研发支出分类',
  `research_template` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否研发专项模板',
  `name` varchar(128) NOT NULL COMMENT '模板名称',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `auto_generate` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否自动生成',
  `default_summary` varchar(255) DEFAULT NULL COMMENT '默认摘要',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) NOT NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) NOT NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_finance_voucher_template_ledger_biz` (`ledger_id`,`biz_type`,`deleted`),
  KEY `idx_finance_voucher_template_page` (`ledger_id`,`biz_type`,`status`,`deleted`,`id`)
) ENGINE=InnoDB AUTO_INCREMENT=132307 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='ERP 财务凭证模板';
/*!40101 SET character_set_client = @saved_cs_client */;

