DROP TABLE IF EXISTS `erp_lease_contract`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `erp_lease_contract` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `no` varchar(64) NOT NULL COMMENT '合同编号',
  `name` varchar(200) NOT NULL COMMENT '合同名称',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `supplier_name` varchar(200) DEFAULT NULL COMMENT '供应商名称（冗余）',
  `start_date` date NOT NULL COMMENT '开始日期',
  `end_date` date NOT NULL COMMENT '结束日期',
  `monthly_rent` decimal(20,2) NOT NULL COMMENT '月租金',
  `payment_cycle` int DEFAULT '1' COMMENT '付款周期（月）',
  `total_amount` decimal(20,2) DEFAULT NULL COMMENT '合同总金额',
  `cost_center_id` bigint DEFAULT NULL COMMENT '成本中心ID（部门ID）',
  `status` tinyint DEFAULT '0' COMMENT '状态：0-草稿 10-生效 20-到期 30-终止',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `file_url` varchar(500) DEFAULT NULL COMMENT '合同附件URL',
  `creator` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_no` (`no`),
  KEY `idx_supplier_id` (`supplier_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='租赁合同表';
