CREATE TABLE `erp_lease_contract_approval` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `lease_contract_id` bigint NOT NULL COMMENT '租赁合同ID',
  `lease_contract_no` varchar(64) DEFAULT NULL COMMENT '租赁合同编号',
